  document.querySelectorAll('[data-delete-program]').forEach(el=>once(el,'click',()=>confirm('프로그램을 삭제할까요?','프로그램과 연결된 댓글이 함께 삭제됩니다.','삭제',()=>{const id=Number(el.dataset.deleteProgram);programs=programs.filter(p=>p.id!==id);delete comments[id];persist();render()})));
  document.querySelectorAll('[data-delete-review]').forEach(el=>once(el,'click',()=>confirm('리뷰를 삭제할까요?','삭제한 리뷰는 복구할 수 없습니다.','삭제',()=>{reviews.splice(Number(el.dataset.deleteReview),1);persist();render()})));
  document.querySelectorAll('[data-edit-review]').forEach(el=>once(el,'click',()=>{editingReview=Number(el.dataset.editReview);openModal(reviewModal());window.currentRating=Number(reviews[editingReview].rating)||5;document.querySelectorAll('[data-rating]').forEach(b=>b.classList.toggle('active',Number(b.dataset.rating)<=window.currentRating))}));
  once($('review-sort'),'change',()=>{reviewSort=$('review-sort').value;render()});
  document.querySelectorAll('[data-account-detail]').forEach(el=>once(el,'click',()=>accountDetail(Number(el.dataset.accountDetail))));
