  document.querySelectorAll('[data-delete-account]').forEach(el=>once(el,'click',()=>confirm('계정을 삭제할까요?','계정과 연결된 강사 프로필을 삭제합니다.','삭제',()=>{const record=adminAccountRows[Number(el.dataset.deleteAccount)];if(record){people=people.filter(p=>p.id!==record.id);instructors=instructors.filter(p=>p.id!==record.id);const removedPrograms=programs.filter(p=>p.owner===record.id);removedPrograms.forEach(p=>delete comments[p.id]);programs=programs.filter(p=>p.owner!==record.id);reviews=reviews.filter(r=>r.authorId!==record.id&&r.instructorId!==record.id);conversations=conversations.filter(c=>c.ownerId!==record.id&&c.teacherId!==record.id);persist();recordLog('계정 삭제')}$('form-modal').close();render()})));
  document.querySelectorAll('[data-rating]').forEach(el=>once(el,'click',()=>{window.currentRating=Number(el.dataset.rating);document.querySelectorAll('[data-rating]').forEach(button=>button.classList.toggle('active',Number(button.dataset.rating)<=window.currentRating))}));
  document.querySelectorAll('[data-page]').forEach(el=>once(el,'click',()=>{if(el.disabled)return;const value=el.dataset.page;currentPage=value==='prev'?Math.max(1,currentPage-1):value==='next'?currentPage+1:Number(value);render()}));
  once($('program-sort'),'change',()=>{currentSort=$('program-sort').value;currentPage=1;selectedPost=0;render()});
  once($('.table-search'),'input',e=>document.querySelectorAll('.table-wrap tbody tr').forEach(row=>row.hidden=!row.innerText.toLowerCase().includes(e.target.value.toLowerCase())));
