function openModal(content){$('form-modal').innerHTML=content;$('form-modal').showModal();bind()}
function action(name,e,el){
  if(name==='profile'){$('profile-popover')?.classList.toggle('hidden');return}
  if(name==='logout')return confirm('로그아웃할까요?','현재 계정에서 로그아웃합니다.','로그아웃',()=>{user=null;sessionStorage.removeItem('teacherpick-proto-v4:user');go('home')});
  if(name==='admin-logout')return confirm('관리자 로그아웃','운영 콘솔에서 로그아웃하시겠습니까?','로그아웃',()=>{recordLog('관리자 로그아웃');admin=false;sessionStorage.removeItem('teacherpick-proto-v4:admin');go('admin-login')});
  if(name==='write-post'){if(!user){go('login');return}if(user.role!=='instructor'){toast('프로그램 등록은 강사 계정에서 이용할 수 있습니다.');return}editingProgram=null;go('program');return}
  if(name==='new-program'){if(user?.role!=='instructor'){toast('강사 계정만 프로그램을 등록할 수 있습니다.');return}editingProgram=null;go('program');return}
  if(name==='cancel-program'){editingProgram=null;go('programs');return}
  if(name==='edit-program-post'){editingProgram=Number(selectedPost);go('program');return}
  if(name==='delete-program-post')return confirm('프로그램 게시물을 삭제할까요?','프로그램과 댓글이 함께 삭제되며 복구할 수 없습니다.','삭제',()=>{programs=programs.filter(p=>p.id!==selectedPost);delete comments[selectedPost];selectedPost=programs[0]?.id||0;persist();render()});
  if(name==='review'){if(!user){go('login');return}if(!programs.length){toast('리뷰를 작성할 등록 프로그램이 없습니다.');return}editingReview=null;return openModal(reviewModal())}
  if(name==='leave-conversation')return confirm('대화방에서 나갈까요?','대화 목록에서 이 방을 제거합니다.','나가기',()=>{conversations.splice(selectedConversation,1);selectedConversation=0;persist();render()});
  if(name==='reply'){if(!user){toast('답글 작성은 로그인 후 이용할 수 있습니다.');go('login');return}el.closest('.comment')?.querySelector('.reply-compose')?.classList.toggle('hidden');return}
  if(name==='require-login'){toast('댓글을 작성하려면 로그인해 주세요.');go('login');return}
  if(name==='contact-instructor'){if(!user){go('login');return}const instructor=instructors.find(x=>String(x.id)===String(selectedInstructor))||instructors[0];if(!instructor)return;let index=conversations.findIndex(c=>c.teacherId===instructor.id&&c.ownerId===user.id);if(index<0){conversations.unshift({id:Date.now(),teacherId:instructor.id,ownerId:user.id,name:instructor.name,subject:instructor.subject||'수업 문의',preview:'대화를 시작해 보세요.',unread:0,messages:[]});index=0;persist()}selectedConversation=index;go('messages');return}
  if(name==='send-code'){const email=$('email-input')?.value.trim().toLowerCase(),account=people.find(p=>p.email===email),state=$('verify-state');if(!email||!account||(user&&route()==='password'&&email!==user.email.toLowerCase())){state.textContent='가입한 이메일 주소를 확인해 주세요.';state.className='verify-state error';return}const bytes=crypto.getRandomValues(new Uint32Array(1))[0],code=String(bytes%1000000).padStart(6,'0');sessionStorage.setItem('teacherpick-proto-v4:recovery',JSON.stringify({email,code,mode:route()==='password'?'change':'forgot',expires:Date.now()+300000}));state.textContent=`로컬 미리보기 인증번호 ${code} · 이메일 발송 연동 전`;state.className='verify-state success';return}
  if(name==='search-teachers'){sessionStorage.setItem('teacherpick-proto-v4:search',$('teacher-search')?.value.trim()||'');selectedInstructor=0;render();return}
  if(name==='close-modal')$('form-modal').close();
}
async function submit(e){e.preventDefault();const form=e.currentTarget,kind=form.dataset.form;const val=id=>$(id)?.value.trim()||'';
  if(kind==='quick-search'){sessionStorage.setItem('teacherpick-proto-v4:search',form.querySelector('input').value.trim());go('search');return}
  if(kind==='program-search'){sessionStorage.setItem('teacherpick-proto-v4:program-query',val('program-search').toLowerCase());currentPage=1;selectedPost=0;render();return}
  if(kind==='login'){const account=people.find(p=>(p.email===val('login-id')||p.username===val('login-id')));if(!account||!await verifyPassword(val('login-password'),account.passwordHash)){toast('아이디 또는 비밀번호를 확인해 주세요.');return}const {passwordHash,...safeUser}=account;user=safeUser;sessionWrite('teacherpick-proto-v4:user',user);go('home');return}
  if(kind==='signup'){
    const error=$('signup-error'),email=val('email-input').toLowerCase(),username=val('id-input').toLowerCase(),password=val('password-input'),role=val('signup-role');
    const fail=message=>{if(error)error.textContent=message;toast(message)};
    if(!val('name-input')||!val('school-input')||!email||!username||!password||!val('password-check'))return fail('필수 항목을 모두 입력해 주세요.');
    if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email))return fail('이메일 주소를 확인해 주세요.');
    if(username.length<6)return fail('아이디는 6자 이상 입력해 주세요.');
    if(password.length<8)return fail('비밀번호는 8자 이상 입력해 주세요.');
    if(password!==val('password-check'))return fail('비밀번호가 일치하지 않습니다.');
    if(role==='instructor'&&!val('signup-subject'))return fail('강의 분야를 입력해 주세요.');
    if(!$('signup-terms')?.checked)return fail('이용약관 및 개인정보 수집·이용에 동의해 주세요.');
    if(people.some(p=>(p.email||'').toLowerCase()===email))return fail('이미 가입된 이메일입니다. 로그인하거나 다른 이메일을 사용해 주세요.');
    if(people.some(p=>(p.username||'').toLowerCase()===username))return fail('이미 사용 중인 아이디입니다. 다른 아이디를 입력해 주세요.');
    if(!globalThis.crypto?.subtle)return fail('이 주소에서는 안전한 비밀번호 저장을 지원하지 않습니다. http://127.0.0.1:8000 으로 접속해 주세요.');
    const id=Date.now();
    try{
      const credential=await hashPassword(password),account={id,name:val('name-input'),school:val('school-input'),email,phone:val('phone-input'),username:val('id-input'),role,createdAt:new Date().toISOString(),passwordHash:credential};
      people.push(account);
      if(role==='instructor')instructors.unshift({id,name:account.name,email:account.email,school:account.school,subject:val('signup-subject'),skills:val('signup-skills'),audience:val('signup-audience'),about:val('signup-about')});
      persist();const {passwordHash,...safeUser}=account;user=safeUser;sessionWrite('teacherpick-proto-v4:user',user);toast('회원가입이 완료되었습니다.');go('home');return
    }catch(err){people=people.filter(p=>p.id!==id);instructors=instructors.filter(p=>p.id!==id);console.error('signup failed',err);return fail('회원가입 정보를 저장하지 못했습니다. 브라우저 저장 공간을 확인한 뒤 다시 시도해 주세요.')}
  }
  if(kind==='admin-login'){if(val('login-id')==='admin'&&val('login-password')==='admin1234'){admin=true;sessionStorage.setItem('teacherpick-proto-v4:admin','true');recordLog('관리자 로그인');go('admin-accounts')}else toast('관리자 계정을 확인해 주세요.');return}
  if(kind==='forgot'){const account=people.find(p=>p.email===val('email-input').toLowerCase());if(!account)return toast('가입된 이메일을 찾을 수 없습니다.');if(user&&route()==='password'&&account.email!==user.email.toLowerCase())return toast('로그인한 계정의 이메일을 확인해 주세요.');let recovery;try{recovery=JSON.parse(sessionStorage.getItem('teacherpick-proto-v4:recovery'))}catch{}if(!recovery||recovery.email!==account.email||recovery.expires<Date.now()||recovery.code!==val('verify-code'))return toast('인증번호를 확인하거나 다시 발급해 주세요.');recovery.verified=true;sessionStorage.setItem('teacherpick-proto-v4:recovery',JSON.stringify(recovery));go('reset-password');return}
  if(kind==='reset-password'){let recovery;try{recovery=JSON.parse(sessionStorage.getItem('teacherpick-proto-v4:recovery'))}catch{}if(!recovery?.verified||recovery.expires<Date.now())return go(recovery?.mode==='change'?'password':'forgot');if(val('password-input').length<8||val('password-input')!==val('password-check'))return toast('새 비밀번호를 확인해 주세요.');const account=people.find(p=>p.email===recovery.email);if(!account)return toast('가입된 이메일을 찾을 수 없습니다.');const keepSession=recovery.mode==='change'&&user?.email?.toLowerCase()===account.email.toLowerCase();account.passwordHash=await hashPassword(val('password-input'));sessionStorage.removeItem('teacherpick-proto-v4:recovery');persist();toast('비밀번호를 변경했습니다.');go(keepSession?'home':'login');return}
  if(kind==='program'){if(user?.role!=='instructor')return toast('강사 계정만 프로그램을 등록할 수 있습니다.');const files=[...($('program-file')?.files||[])].map(f=>f.name);const existing=programs.find(p=>p.id===editingProgram);const item={id:editingProgram||Date.now(),owner:user.id,title:val('program-title'),subject:val('program-subject'),skills:val('program-skills'),description:val('program-description'),audience:val('program-audience'),schedule:val('program-schedule'),price:val('program-price'),attachments:files.length?files:(existing?.attachments||[]),author:user.name,school:user.school,date:existing?.date||new Date().toLocaleString('ko-KR'),createdAt:existing?.createdAt||Date.now(),comments:existing?.comments||0};if(editingProgram)programs=programs.map(p=>p.id===editingProgram&&p.owner===user.id?item:p);else programs.unshift(item);editingProgram=null;persist();toast('프로그램을 등록했습니다.');go('community');return}

  if(kind==='comment'){if(!user){toast('댓글을 작성하려면 로그인해 주세요.');go('login');return}if(!val('comment-input'))return toast('댓글 내용을 입력해 주세요.');postComments().push({id:Date.now(),authorId:user.id,author:user.name,body:val('comment-input'),time:'방금 전',replies:[],own:true});const p=programs.find(p=>p.id===selectedPost);if(p)p.comments=postComments().reduce((n,c)=>n+1+(c.replies||[]).length,0);persist();render();return}
  if(kind==='reply'){if(!user){toast('답글 작성은 로그인 후 이용할 수 있습니다.');go('login');return}const parent=postComments().find(c=>String(c.id)===form.querySelector('input[type=hidden]').value),body=form.querySelector('.reply-input')?.value.trim();if(!parent||!body)return toast('답글 내용을 입력해 주세요.');parent.replies ||= [];parent.replies.push({id:Date.now(),authorId:user.id,author:user.name,body,own:true});const p=programs.find(p=>p.id===selectedPost);if(p)p.comments=postComments().reduce((n,c)=>n+1+(c.replies||[]).length,0);persist();render();return}
  if(kind==='message'){const c=conversations[selectedConversation];if(!c)return;const text=val('message-input'),file=$('message-file')?.files[0]?.name;if(!text&&!file)return;c.messages ||= [];c.messages.push({from:'me',text:text||'파일을 첨부했습니다.',file,time:'방금 전'});c.preview=text||file;persist();render();return}
  if(kind==='review'){const program=programs.find(p=>String(p.id)===val('review-program'));if(!program)return toast('수강 프로그램을 선택해 주세요.');const item={program:program.title,programId:program.id,instructorId:program.owner,authorId:user.id,author:user.name,text:val('review-text'),rating:window.currentRating||5,date:new Date().toLocaleDateString('ko-KR'),timestamp:Date.now()};if(editingReview!==null&&reviews[editingReview]?.authorId===user.id)reviews[editingReview]={...reviews[editingReview],...item};else reviews.unshift(item);editingReview=null;persist();$('form-modal').close();go('reviews');return}
  if(kind==='account'){if(people.some(p=>p.id!==user.id&&p.email===val('account-email').toLowerCase()))return toast('이미 사용 중인 이메일입니다.');user={...user,name:val('account-name'),email:val('account-email').toLowerCase(),school:val('account-school'),phone:val('account-phone')};people=people.map(p=>p.id===user.id?{...p,name:user.name,email:user.email,school:user.school,phone:user.phone}:p);instructors=instructors.map(p=>p.id===user.id?{...p,name:user.name,email:user.email,school:user.school}:p);saveSessionUser();persist();toast('계정 정보를 저장했습니다.');render();return}
  if(kind==='password'){const account=people.find(p=>p.id===user.id);if(!await verifyPassword(val('current-password'),account?.passwordHash))return toast('현재 비밀번호가 일치하지 않습니다.');if(val('new-password').length<8||val('new-password')!==val('confirm-password'))return toast('새 비밀번호를 확인해 주세요.');account.passwordHash=await hashPassword(val('new-password'));persist();toast('비밀번호를 변경했습니다.');render()}
}
function accountDetail(index){const account=adminAccountRows[index];if(!account)return;confirmAction=null;$('form-modal').innerHTML=`<div class="modal-card"><header><div><span class="eyebrow">ACCOUNT DETAIL</span><h2>계정 상세 정보</h2></div><button class="close-button" data-action="close-modal">×</button></header><div class="account-detail-grid"><b>이름</b><span>${esc(account.name)}</span><b>유형</b><span>${account.role==='teacher'?'교사':'강사'}</span><b>이메일</b><span>${esc(account.email)}</span><b>학교·기관</b><span>${esc(account.school||'미등록')}</span><b>상태</b><span><i class="status-pill">활성</i></span><b>가입일</b><span>${esc(new Date(account.createdAt||Date.now()).toLocaleDateString('ko-KR'))}</span></div><div class="form-actions"><button class="danger-button" data-delete-account="${index}">계정 삭제</button><span></span><button class="secondary-button" data-action="close-modal">닫기</button></div></div>`;$('form-modal').showModal();bind()}
